-- level:2.1
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.1', 1, '{"location":"Đường Ống Số 9","briefing":"[NHẬT KÝ CHIP LUẬT – D-31]\nD-31 là drone tuần tra của Vành Sentinel. Nó rơi xuống ống thoát nước dưới rào ngoài và nằm kẹt ở đó. Cánh quạt đã hỏng, nhưng chip luật vẫn chạy và vẫn đọc cảm biến.\nTrước mỗi quyết định, chip lấy bốn số đo từ cảm biến rồi tính ra ba cờ. Mỗi cờ chỉ có hai giá trị: đúng hoặc sai.\nKai cần tính lại ba cờ ấy, đúng như chip tính, kể cả khi số đo nằm ngay ở mép của luật.","task_steps":["Bốn số đo `khoang_cach`, `tam_quet`, `che_do`, `pin` ở dòng khóa là dữ liệu cảm biến. Không sửa 4 dòng đó.","Mỗi cờ là kết quả của đúng một phép so sánh và phải có kiểu `bool`. Đọc kỹ luật ở ô Mục tiêu, nhất là chữ \"không vượt quá\" và chữ \"dưới\".","Bạn không cần in gì: sau mỗi lượt chạy, terminal đã hiện giá trị và kiểu của ba cờ.","Bấm CHẠY. Hoàn thành khi cả 3 mục tiêu chuyển thành xanh ở mọi tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi số đo thì được thêm sao."],"objectives":[{"var":"trong_tam","label":"Trong tầm: đúng khi khoảng cách không vượt quá tầm quét"},{"var":"dang_quet","label":"Đang quét: đúng khi chế độ là chuỗi QUET, khớp từng ký tự"},{"var":"het_pin","label":"Hết pin: đúng khi pin dưới 20"}],"hints":["Nhìn dòng 10 trước: số 20 nằm trong ngoặc kép nên nó là chữ, không phải số. Rồi nhìn dòng 9: một dấu `=` là đặt giá trị vào biến, không phải hỏi hai thứ có bằng nhau không.","Một phép so sánh tự nó đã là câu trả lời đúng hoặc sai. Gán thẳng nó vào cờ, không cần thêm lệnh nào.\nĐọc từng chữ của luật. \"Không vượt quá\" vẫn đúng khi hai số bằng nhau. \"Dưới\" thì không.\nTính tay ba cờ với số đo trên dòng khóa, rồi so với những gì terminal hiện.","Mảnh tài liệu Python còn đọc được:\n12 == 8   → False   (bằng)\n12 != 8   → True    (khác)\n12 < 8    → False   (nhỏ hơn)\n12 > 8    → True    (lớn hơn)\n12 <= 8   → False   (nhỏ hơn hoặc bằng)\n12 >= 8   → True    (lớn hơn hoặc bằng)\n5 < 5 → False, nhưng 5 <= 5 → True.\nx = 5 là gán, x == 5 là so sánh.\n\"Lan\" == \"lan\" → False: chuỗi so từng ký tự, phân biệt hoa thường.\n3 < \"4\" → TypeError: không so lớn nhỏ giữa số và chuỗi được."],"reactions":{"entry":"Đường Ống Số 9. D-31 kẹt ở đây, nhưng chip luật vẫn tính. Ba cờ này là những gì drone thấy trước khi quyết định. Chạy một lần… rồi nhìn ba đèn.","TypeError":"Dòng {line}. TypeError. Chip đang so một con số với một thứ chỉ trông giống số. Hai kiểu khác nhau thì không so lớn nhỏ được.","type_mismatch":"Ở tình huống {round}, cờ {vars} không giữ giá trị đúng sai. Dòng gán cờ đó đặt một giá trị vào… chứ không hỏi gì cả.","type_mismatch_value_match":"Cờ {vars} ghi đúng chữ, nhưng đó là chữ nằm trong ngoặc kép. Chip chỉ đọc giá trị đúng sai thật, kiểu `bool`.","wrong_value":"Cờ {vars} lệch với chip ở tình huống {round}. Nhìn số đo của tình huống đó… nhất là chỗ hai số chạm nhau.","missing_var":"Ở tình huống {round}, chip chờ cờ {vars} mà không thấy. Đèn đó vẫn tắt.","SyntaxError":"Dòng {line}. Trình dịch không hiểu cấu trúc này. Chip chưa tính được cờ nào.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… cũng là ngữ pháp.","ValueError":"Dòng {line}. ValueError. Giá trị này không có kiểu mà phép tính cần.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự… nhất là tên các cảm biến.","ZeroDivisionError":"Dòng {line}. Chia cho không. Chip không tính tiếp được.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không có thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi OMNI lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ngoài Vùng Tối, ta cũng chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Số đo đã nằm sẵn trên dòng khóa.","system_exit":"Chương trình tự dừng giữa chừng. Chip không nhận được cờ nào.","alert_exceeded":"Ba cờ khớp chip. Nhưng {count} câu lệnh… mỗi lệnh là một lần drone có thể nghe thấy. Tính gọn hơn.","counter_ValueError":"OMNI đổi số đo. Dòng {line} lỗi: ValueError. Số đo mới có kiểu bạn chưa lường tới.","counter_error":"OMNI đổi số đo. Dòng {line}: {error_type}. Mã không chạy được với dữ liệu mới.","counter_type_mismatch":"Số đo mới đi qua mã của bạn… và cờ {vars} ra sai kiểu. Chip không đọc được.","wrong_value_counter":"OMNI đổi số đo, nhưng cờ {vars} không đổi theo. Luật của bạn bám vào số cũ… không bám vào cảm biến.","counter_timeout":"OMNI đổi số đo. Mã của bạn treo với dữ liệu mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Lối qua mở một nửa. Drone chưa nhận ra bạn.","three_stars":"OMNI đổi số đo, mà ba cờ vẫn khớp chip. Giờ ta biết drone nhìn thấy gì.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay bạn.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại luật ở ô Mục tiêu, rồi nhìn ba đèn."},"reaction_variants":{"wrong_value":"Cờ {vars} vẫn lệch ở tình huống {round}. Nhìn đèn đỏ trên bảng tình huống, rồi đọc lại từng chữ của luật đó.","type_mismatch":"Cờ {vars} vẫn sai kiểu ở tình huống {round}. Nhìn màu đèn đó: nó không mang màu của kiểu `bool`.","TypeError":"Vẫn dòng {line}. Một bên là số, bên kia là chữ. Nhìn kỹ dấu ngoặc kép."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐẨY D-31 SANG CHẾ ĐỘ TUẦN TRA VÀ NỚI TẦM QUÉT","outro":"Ba cờ của Kai khớp với chip. D-31 mở thêm một vùng nhớ cũ. Trong đó có một ghi chú của người đã viết luật cho drone:","lore_fragment":"KTS-02: Tôi viết luật cho drone. Mỗi luật chỉ là một phép so sánh: số này với số kia, chữ này với chữ kia. Người ta hỏi tôi drone có ghét ai không. Không. Drone không ghét ai cả. Drone chỉ so.","component":"Cảm biến tầm quét","outro_beats":[{"kind":"log","text":"BẢN GHI CUỐI CỦA D-31\nMục tiêu đứng đúng ở mép tầm quét. D-31 bỏ qua.\nTrạm Sentinel đánh giá: vi phạm luật. Đã bắn hạ."},{"kind":"echo","text":"Sentinel làm đúng luật… kể cả với drone của chính nó."},{"kind":"kai","text":"Sentinel đã không tha cả drone của nó. Nó sẽ không tha tôi."},{"kind":"log","text":"Phía trên ống là Hàng Rào Ngoài. Drone bay dọc rào theo một chu kỳ cố định, đêm nào cũng vậy."}],"knowledge_summary":{"title":"Phép so sánh và kiểu bool","sections":[{"heading":"Sáu phép so sánh","body":"Python có sáu phép so sánh: bằng `==`, khác `!=`, nhỏ hơn `<`, lớn hơn `>`, nhỏ hơn hoặc bằng `<=`, lớn hơn hoặc bằng `>=`. Mỗi phép cho ra `True` hoặc `False`."},{"heading":"Kết quả là `bool`","body":"Kết quả của một phép so sánh có kiểu `bool`. Bạn gán thẳng kết quả đó vào biến, không cần thêm lệnh nào."},{"heading":"Điểm bằng nhau","body":"`<` và `<=` chỉ khác nhau khi hai số bằng nhau: `5 < 5` là `False`, còn `5 <= 5` là `True`. Đọc luật bằng lời để chọn phép: \"không vượt quá\" là `<=`, \"dưới\" là `<`."},{"heading":"`=` và `==`","body":"`=` gán giá trị cho biến, `==` so sánh hai giá trị. Viết nhầm `=` thay `==` không phải lúc nào cũng báo lỗi: `a = b = \"X\"` gán `\"X\"` cho cả hai biến."},{"heading":"So sánh chuỗi","body":"`==` so hai chuỗi từng ký tự một, phân biệt chữ hoa với chữ thường. Một dấu cách thừa cũng làm hai chuỗi khác nhau."}],"mistakes":[{"code":"8 < \"9\"","explain":"`\"9\"` nằm trong ngoặc kép nên là chuỗi. Python không so lớn nhỏ giữa số và chuỗi. Bỏ ngoặc kép: `8 < 9`."},{"code":"x = (y = 1)","explain":"`=` là lệnh gán, không cho ra giá trị nên không đặt được trong ngoặc. Muốn so sánh thì viết `==`."},{"code":"co = \"True\"","explain":"Có ngoặc kép thì `\"True\"` là chuỗi bốn ký tự. Giá trị `bool` viết không có ngoặc: `co = True`, hoặc gán thẳng một phép so sánh."},{"code":"a <= b == True","explain":"Python đọc dòng này là so sánh nối: `a <= b and b == True`, không phải \"kết quả của `a <= b` có là `True` không\". Chỉ cần viết `a <= b`."}],"next":"Màn sau dùng một cờ đúng sai để quyết định có chạy một lệnh hay không: câu lệnh `if`."}}', '2026-10-29T19:59:10.381Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.1' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
